  "test": "import { describe, expect, it } from 'vitest';
import { priceCart, Promotion } from '../src/pricing';

describe('priceCart - límite de descuento', () => {
  it('no permite que el descuento total exceda el subtotal ni genere totales negativos', () => {
    const lines = [
      {
        sku: 'POLO-ALG-M',
        qty: 1,
        unitPriceCents: 1000,
        category: 'moda',
      },
    ];

    const promotions: Promotion[] = [
      {
        type: 'COUPON_FIXED',
        code: 'GRANDE',
        amountCents: 1500,
        minPurchaseCents: 500,
      },
    ];

    const totals = priceCart(lines, promotions, 'GRANDE');

    expect(totals.subtotalCents).toBe(1000);
    expect(totals.discountCents).toBe(1000);
    expect(totals.totalCents).toBe(0);
  });
});
